const express = require('express');
const router = express.Router();
const controller = require('../controllers/alertController');
const { validateIdParam, validateAlertInput, validateAlertStatusPatch } = require('../middleware/validate');

// GET /api/alerts
router.get('/', controller.getAllAlerts);

// GET /api/alerts/dynamic?lat=&lon= — arbitrary searched location
router.get('/dynamic', controller.getDynamicAlerts);

// GET /api/alerts/scenario — alerts generated by manual AI Disaster Check
router.get('/scenario', controller.getScenarioAlerts);

// PATCH /api/alerts/scenario/:id — update a scenario alert's status
router.patch('/scenario/:id', validateIdParam('id'), controller.updateScenarioAlertStatus);

// POST /api/alerts
router.post('/', validateAlertInput, controller.createAlert);

// PATCH /api/alerts/:id
router.patch('/:id', validateIdParam('id'), validateAlertStatusPatch, controller.updateAlertStatus);

module.exports = router;
